function decode(b64chunks) {
  const bin = atob(b64chunks.join(''));
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export function faviconPngBytes() {
  return decode(FAVICON_PNG_B64);
}

export function appleTouchIconBytes() {
  return decode(APPLE_TOUCH_ICON_B64);
}
